'use strict';
const KEY='daylist.tasks.v1';
const CATEGORIES={work:'Work',learning:'Learning',personal:'Personal'};
const STATUSES={todo:'To do',progress:'In progress',done:'Done'};
const $=s=>document.querySelector(s);
const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const now=new Date();let today=localDate(now),month=new Date(now.getFullYear(),now.getMonth(),1);
let tasks=[],filter='all',category=null,dateFilter=null,editing=null,deleted=null,timer,storageBlocked=false;
const validDate=s=>s===''||(/^\d{4}-\d{2}-\d{2}$/.test(s)&&localDate(new Date(s+'T12:00:00'))===s);
const validTask=t=>t&&typeof t.id==='string'&&typeof t.title==='string'&&t.title.trim().length>0&&t.title.length<=200&&Object.hasOwn(CATEGORIES,t.category)&&Object.hasOwn(STATUSES,t.status)&&typeof t.date==='string'&&validDate(t.date)&&Number.isFinite(t.created);
function storageError(message){$('#storage-error').textContent=message;$('#storage-error').hidden=false;}
function load(){try{const raw=localStorage.getItem(KEY);if(raw!==null){const data=JSON.parse(raw);if(data.version!==1||!Array.isArray(data.tasks)||!data.tasks.every(validTask)||new Set(data.tasks.map(t=>t.id)).size!==data.tasks.length)throw new Error('Invalid data');tasks=data.tasks;}return true;}catch{storageBlocked=true;storageError('Your saved tasks could not be read. They have not been overwritten. Allow browser storage or restore valid saved data, then reload to try again.');return false;}}
function commit(next){if(storageBlocked){storageError('Changes cannot be saved until browser storage is available. Your existing saved data has not been changed.');return false;}try{localStorage.setItem(KEY,JSON.stringify({version:1,tasks:next}));tasks=next;$('#storage-error').hidden=true;render();return true;}catch{storageError('This change could not be saved. Check available browser storage, then try again.');return false;}}
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function announce(text,undo=false){clearTimeout(timer);$('#toast-text').textContent=text;$('#toast').hidden=false;$('#undo').hidden=!undo;if(!undo)deleted=null;timer=setTimeout(()=>{$('#toast').hidden=true;deleted=null;},undo?12000:4000);}
function openEditor(task){editing=task?.id??null;$('#task-form').reset();$('#task-title').value=task?.title??'';$('#task-date').value=task?.date??dateFilter??'';$('#task-status').value=task?.status??'todo';$(`input[name=category][value=${task?.category??category??'work'}]`).checked=true;$('#dialog-title').textContent=task?'Edit task':'New task';$('#save-task').textContent=task?'Save changes':'Create task';$('#form-error').textContent='';$('#task-dialog').showModal();$('#task-title').focus();}
function closeEditor(){$('#task-dialog').close();editing=null;}
function changeStatus(id,status){if(!Object.hasOwn(STATUSES,status))return false;return commit(tasks.map(t=>t.id===id?{...t,status}:t));}
function resetFilters(){filter='all';category=null;dateFilter=null;render();}
function dateLabel(value){if(value===today)return 'Today';const tomorrow=new Date(today+'T12:00:00');tomorrow.setDate(tomorrow.getDate()+1);if(value===localDate(tomorrow))return 'Tomorrow';return new Date(value+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',...(value.slice(0,4)!==today.slice(0,4)?{year:'numeric'}:{})});}
function renderTask(task){const row=el('article',`task ${task.category}${task.status==='done'?' done':''}`);const check=el('input','check');check.type='checkbox';check.checked=task.status==='done';check.setAttribute('aria-label',`${task.status==='done'?'Reopen':'Complete'} ${task.title}`);check.addEventListener('change',()=>{if(changeStatus(task.id,check.checked?'done':'todo')){announce(check.checked?'Task completed.':'Task reopened.');const updated=[...document.querySelectorAll('.task .check')].find(e=>e.dataset.id===task.id);updated?.focus();}else check.checked=task.status==='done';});check.dataset.id=task.id;const main=el('div','task-main');const title=el('button','task-title',task.title);title.setAttribute('aria-label',`Edit ${task.title}`);title.addEventListener('click',()=>openEditor(task));const meta=el('div','task-meta');meta.append(el('span','category-tag',CATEGORIES[task.category]));if(task.date)meta.append(el('span',`due${task.date<today&&task.status!=='done'?' overdue':''}`,`${task.date<today&&task.status!=='done'?'Overdue · ':''}${dateLabel(task.date)}`));if(task.status==='progress')meta.append(el('span',null,'In progress'));main.append(title,meta);const actions=el('div','task-actions');const edit=el('button','icon-button','✎');edit.setAttribute('aria-label',`Edit task: ${task.title}`);edit.onclick=()=>openEditor(task);const remove=el('button','icon-button','×');remove.setAttribute('aria-label',`Delete task: ${task.title}`);remove.onclick=()=>{if(commit(tasks.filter(t=>t.id!==task.id))){deleted=task;announce('Task deleted.',true);$('#undo').focus();}};actions.append(edit,remove);row.append(main,actions,check);return row;}
function renderCalendar(){$('#month-label').textContent=month.toLocaleDateString(undefined,{month:'long',year:'numeric'});const grid=$('#calendar');grid.replaceChildren();const offset=(month.getDay()+6)%7;for(let i=0;i<offset;i++)grid.append(el('span'));const last=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();for(let d=1;d<=last;d++){const dt=new Date(month.getFullYear(),month.getMonth(),d),iso=localDate(dt);const btn=el('button',`${iso===today?'today ':''}${iso===dateFilter?'selected ':''}${tasks.some(t=>t.date===iso)?'has-tasks':''}`,String(d));btn.setAttribute('aria-label',`Tasks due ${dt.toLocaleDateString(undefined,{dateStyle:'full'})}`);btn.setAttribute('aria-pressed',String(iso===dateFilter));if(iso===today)btn.setAttribute('aria-current','date');btn.onclick=()=>{dateFilter=dateFilter===iso?null:iso;render();};grid.append(btn);}$('#calendar-reset').textContent=dateFilter?'Clear date':'All dates';}
function render(){today=localDate(new Date());$('#today-label').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});const hour=new Date().getHours();$('#greeting').textContent=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';Object.keys(STATUSES).forEach(s=>{$(`#${s}-count`).textContent=tasks.filter(t=>t.status===s).length;});const done=tasks.filter(t=>t.status==='done').length;$('#nav-count').textContent=tasks.length;$('#progress-bar').style.width=`${tasks.length?done/tasks.length*100:0}%`;$('#progress-copy').textContent=`${done} of ${tasks.length} ${tasks.length===1?'task':'tasks'} complete`;const percent=tasks.length?Math.round(done/tasks.length*100):0;$('#completion-percent').textContent=`${percent}%`;$('#completion-ring').style.setProperty('--progress',`${percent}%`);const shown=tasks.filter(t=>(filter==='all'||t.status===filter)&&(!category||t.category===category)&&(!dateFilter||t.date===dateFilter)).sort((a,b)=>(a.status==='done')-(b.status==='done')||(a.date||'9999').localeCompare(b.date||'9999')||a.created-b.created);$('#list-count').textContent=shown.length;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));$('#clear-filters').hidden=filter==='all'&&!category&&!dateFilter;$('#task-list').replaceChildren(...shown.map(renderTask));$('#empty').hidden=shown.length>0;$('#empty h3').textContent=dateFilter?'No tasks for this date':tasks.length?'No matching tasks':'No tasks yet';$('#empty p').textContent=tasks.length?'Change the filters or add a task to this view.':'Add a task above, or choose a date to plan ahead.';const displayDate=new Date((dateFilter||today)+'T12:00:00');$('#empty-month').textContent=displayDate.toLocaleDateString(undefined,{month:'short'}).toUpperCase();$('#empty-day').textContent=displayDate.getDate();$('#list-title').firstChild.textContent=dateFilter?`${dateLabel(dateFilter)} `:'All tasks ';$('#categories').replaceChildren(...Object.entries(CATEGORIES).map(([key,name])=>{const b=el('button',`category-filter ${key}`);b.setAttribute('aria-pressed',String(category===key));const label=el('span');label.append(el('span','color-square'),el('span',null,name));b.append(label,el('span',null,String(tasks.filter(t=>t.category===key).length)));b.onclick=()=>{category=category===key?null:key;render();};return b;}));renderCalendar();renderWeek();}

function renderWeek(){
  const base=new Date(today+'T12:00:00');base.setDate(base.getDate()-((base.getDay()+6)%7));
  const days=[];
  for(let i=0;i<7;i++){
    const day=new Date(base);day.setDate(base.getDate()+i);const iso=localDate(day);
    const button=el('button',`week-day${iso===today?' today':''}${tasks.some(t=>t.date===iso)?' has-tasks':''}`);
    button.setAttribute('aria-pressed',String(dateFilter===iso));
    button.setAttribute('aria-label',`Show tasks for ${day.toLocaleDateString(undefined,{dateStyle:'full'})}`);
    button.append(el('span',null,day.toLocaleDateString(undefined,{weekday:'short'})),el('strong',null,String(day.getDate())));
    button.onclick=()=>{dateFilter=dateFilter===iso?null:iso;month=new Date(day.getFullYear(),day.getMonth(),1);render();};days.push(button);
  }
  $('#week-strip').replaceChildren(...days);
}
$('#quick-form').addEventListener('submit',event=>{
  event.preventDefault();const input=$('#quick-title');const title=input.value.trim();
  if(!title){input.setCustomValidity('Enter a task name.');input.reportValidity();return;}
  const task={id:crypto.randomUUID(),title,date:dateFilter||'',category:category||'work',status:filter==='progress'?'progress':'todo',created:Date.now()};
  if(commit([...tasks,task])){input.value='';if(filter==='done')filter='todo';render();announce('Task added.');input.focus();}
});
$('#quick-title').addEventListener('input',()=>$('#quick-title').setCustomValidity(''));

$('#task-form').addEventListener('submit',e=>{e.preventDefault();const title=$('#task-title').value.trim(),date=$('#task-date').value,status=$('#task-status').value,cat=$('input[name=category]:checked').value;if(!title||!validDate(date)){$('#form-error').textContent='Enter a task name and a valid date.';return;}const old=tasks.find(t=>t.id===editing);const task={id:old?.id??crypto.randomUUID(),title,date,status,category:cat,created:old?.created??Date.now()};if(!validTask(task))return;const next=old?tasks.map(t=>t.id===old.id?task:t):[...tasks,task];if(commit(next)){closeEditor();resetFilters();announce(old?'Task updated.':'Task added.');}else $('#form-error').textContent='Could not save. Your input is still here — try again when browser storage is available.';});
$('#new-task').onclick=()=>openEditor();$('#empty-add').onclick=()=>openEditor();$('#close-dialog').onclick=closeEditor;$('#cancel-dialog').onclick=closeEditor;$('#all-nav').onclick=resetFilters;$('#clear-filters').onclick=resetFilters;$('#calendar-reset').onclick=()=>{dateFilter=null;render();};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{filter=b.dataset.status;render();});$('#prev-month').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);renderCalendar();};$('#next-month').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);renderCalendar();};$('#undo').onclick=()=>{if(deleted){const restore=deleted;if(commit([...tasks.filter(t=>t.id!==restore.id),restore])){announce('Task restored.');}}};window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){tasks=[];storageBlocked=false;$('#storage-error').hidden=true;load();render();}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});load();render();
// Optional browser-agent access uses exactly the same persisted state as the UI.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_tasks',description:'Read all tasks saved in this browser, including their status and due date.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input===null||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');if(storageBlocked)throw new Error('Saved tasks are unavailable');return {tasks:tasks.map(t=>({...t}))};}})).catch(()=>{});}catch{}}
